fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn replace(s:&mut String,a:&str,b:&str){assert_eq!(s.matches(a).count(),1,"missing/duplicate {a}");*s=s.replacen(a,b,1)}
fn copy(a:&Path,b:&Path){fs::create_dir_all(b).unwrap();for e in fs::read_dir(a).unwrap(){let e=e.unwrap();let name=e.file_name();if ["target",".git",".cargo-ok",".cargo-checksum.json"].contains(&name.to_str().unwrap()){continue}if e.file_type().unwrap().is_dir(){copy(&e.path(),&b.join(name))}else{fs::copy(e.path(),b.join(name)).unwrap();}}}
fn tree(a:&Path,pins:&mut BTreeMap<String,String>){for e in fs::read_dir(a).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){tree(&e.path(),pins)}else{pins.insert(e.path().display().to_string(),hash(e.path()));}}}
fn main(){let r=Path::new(R);assert!(!r.join("candidate").exists());let m:Value=serde_json::from_slice(&fs::read(M).unwrap()).unwrap();let original=m["source_files_sha256"].as_object().unwrap();assert_eq!(original.len(),172);for(f,h)in original{assert_eq!(hash(Path::new(Z).join(f)),h.as_str().unwrap());}
 let overlay=r.join("overlay");let vendor=overlay.join("vendor/rayon-core");copy(Path::new(V),&vendor);let mut cargo=fs::read_to_string(vendor.join("Cargo.toml")).unwrap();cargo.push_str("\n[workspace]\n");fs::write(vendor.join("Cargo.toml"),cargo).unwrap();fs::copy(r.join("batch_steal.rs"),vendor.join("src/batch_steal.rs")).unwrap();
 let path=vendor.join("src/registry.rs");let old=fs::read_to_string(&path).unwrap();let mut source=old.clone();let field="    pub(super) batch_local_steal: bool,\n";let init="            batch_local_steal: std::env::var(\"ZOPRO_CPU_BATCH_LOCAL_STEAL\").is_ok_and(|s| s == \"1\"),\n";replace(&mut source,"pub(super) struct Registry {",&format!("pub(super) struct Registry {{\n{field}"));replace(&mut source,"            sleep: Sleep::new(n_threads),",&format!("{init}            sleep: Sleep::new(n_threads),"));
 let extract="if self.registry.batch_local_steal {\n                        let (job, available) = batch_steal::transfer(&victim.stealer, &self.worker);\n                        if available != 0 {\n                            self.registry.sleep.new_internal_jobs(available.min(u32::MAX as usize) as u32, true);\n                        }\n                        job\n                    } else { victim.stealer.steal() }";replace(&mut source,"match victim.stealer.steal() {",&format!("match {extract} {{"));
 let mut recovered=source.clone();replace(&mut recovered,field,"");replace(&mut recovered,init,"");replace(&mut recovered,&format!("match {extract} {{"),"match victim.stealer.steal() {");assert_eq!(recovered,old);source.push_str("\n#[path=\"batch_steal.rs\"]\nmod batch_steal;\n");fs::write(path,source).unwrap();
 let mut cargo=fs::read_to_string(Path::new(Z).join("Cargo.toml")).unwrap();cargo.push_str("\n[patch.crates-io]\nrayon-core = { path = \"vendor/rayon-core\" }\n");fs::write(overlay.join("Cargo.toml"),cargo).unwrap();let lock=fs::read_to_string(Path::new(Z).join("Cargo.lock")).unwrap();let mut chunks=lock.split("[[package]]").map(str::to_owned).collect::<Vec<_>>();let mut changed=0;for c in &mut chunks{if c.starts_with("\nname = \"rayon-core\"\n"){*c=c.lines().filter(|l|!l.starts_with("source = ")&&!l.starts_with("checksum = ")).collect::<Vec<_>>().join("\n")+"\n\n";changed+=1}}assert_eq!(changed,1);fs::write(overlay.join("Cargo.lock"),chunks.join("[[package]]")).unwrap();
 for(name,extra)in [("control",None),("candidate",Some(&overlay))]{let mut c=Command::new(X);c.args(["prepare",M,Z]).arg(r.join(name));if let Some(p)=extra{c.arg(p);}let out=c.output().unwrap();fs::write(r.join(format!("prepare-{name}.log")),out.stdout).unwrap();fs::write(r.join(format!("prepare-{name}.stderr.log")),out.stderr).unwrap();assert!(out.status.success());}
 let mut pins=BTreeMap::new();tree(&r.join("control"),&mut pins);tree(&r.join("candidate"),&mut pins);for f in ["design.md","prepare.rs","batch_steal.rs"]{pins.insert(r.join(f).display().to_string(),hash(r.join(f)));}let audit=json!({"source_originals":172,"production_changed":false,"candidate_changed_originals":["Cargo.toml","Cargo.lock"],"original_registry_recovered_exactly":true,"rayon_core":"1.13.0","crossbeam_deque":"0.8.8","runtime_package_versions_edges_unchanged":true,"no_unsafe_production_addition":true,"candidate_registry_sha256":hash(r.join("candidate/vendor/rayon-core/src/registry.rs"))});fs::write(r.join("source-audit.json"),serde_json::to_vec_pretty(&audit).unwrap()).unwrap();fs::write(r.join("source-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();println!("Prepared fresh172control and privateRayon batch-transfer candidate; no SDK yet");
}
